/** Base class for every violation of a business rule raised by the domain. */
export abstract class DomainError extends Error {
  protected constructor(message: string) {
    super(message);
    this.name = new.target.name;
  }
}

/** A value supplied to the domain is malformed (e.g. a non-positive quantity). */
export class InvalidValueError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

/** The requested quantity cannot be reserved because not enough stock is available. */
export class InsufficientStockError extends DomainError {
  constructor(
    readonly productId: string,
    readonly requested: number,
    readonly available: number,
  ) {
    super(`Insufficient stock for product ${productId}: requested ${requested}, available ${available}`);
  }
}

/** The order cannot move from its current status to the requested one. */
export class InvalidTransitionError extends DomainError {
  constructor(
    readonly orderId: string,
    readonly from: string,
    readonly to: string,
  ) {
    super(`Order ${orderId} cannot move from '${from}' to '${to}'`);
  }
}

