import { InvalidTransitionError, InvalidValueError } from './DomainErrors';
import { OrderLine } from './OrderLine';
import { OrderStatus, isCancellable, nextStatus } from './OrderStatus';

/** Entity / aggregate root: a customer's order and its position in the fulfilment lifecycle. */
export class Order {
  private constructor(
    readonly id: string,
    readonly customerId: string,
    readonly lines: readonly OrderLine[],
    readonly placedAt: Date,
    private _status: OrderStatus,
    private _updatedAt: Date,
  ) {}

  static place(id: string, customerId: string, lines: readonly OrderLine[], now: Date): Order {
    if (customerId.trim() === '') {
      throw new InvalidValueError('Customer id must not be empty');
    }
    if (lines.length === 0) {
      throw new InvalidValueError('An order must contain at least one line');
    }
    return new Order(id, customerId, OrderLine.consolidate(lines), now, 'placed', now);
  }

  get status(): OrderStatus {
    return this._status;
  }

  get updatedAt(): Date {
    return this._updatedAt;
  }

  /** Moves the order to `target`, which must be the very next step of the fulfilment sequence. */
  advanceTo(target: OrderStatus, now: Date): void {
    if (nextStatus(this._status) !== target) {
      throw new InvalidTransitionError(this.id, this._status, target);
    }
    this.changeStatus(target, now);
  }

  cancel(now: Date): void {
    if (!isCancellable(this._status)) {
      throw new InvalidTransitionError(this.id, this._status, 'cancelled');
    }
    this.changeStatus('cancelled', now);
  }

  private changeStatus(status: OrderStatus, now: Date): void {
    this._status = status;
    this._updatedAt = now;
  }
}

