/** Every status an order can be in. */
export const ORDER_STATUSES = ['placed', 'paid', 'packed', 'shipped', 'delivered', 'cancelled'] as const;

export type OrderStatus = (typeof ORDER_STATUSES)[number];

/** The only forward path an order may follow, one step at a time. */
const FULFILMENT_SEQUENCE: readonly OrderStatus[] = ['placed', 'paid', 'packed', 'shipped', 'delivered'];

/** Statuses from which an order may still be cancelled (anything before shipping). */
const CANCELLABLE_STATUSES: readonly OrderStatus[] = ['placed', 'paid', 'packed'];

export function isOrderStatus(value: string): value is OrderStatus {
  return (ORDER_STATUSES as readonly string[]).includes(value);
}

/** The status that directly follows `status` in the fulfilment sequence, if any. */
export function nextStatus(status: OrderStatus): OrderStatus | undefined {
  const index = FULFILMENT_SEQUENCE.indexOf(status);
  return index === -1 ? undefined : FULFILMENT_SEQUENCE[index + 1];
}

export function isCancellable(status: OrderStatus): boolean {
  return CANCELLABLE_STATUSES.includes(status);
}

