import { InsufficientStockError, InvalidValueError } from './DomainErrors';

/**
 * Entity: a catalogue product and its stock.
 * `onHand` is physically in the warehouse; `reserved` is the part of it held for open orders.
 */
export class Product {
  private constructor(
    readonly id: string,
    readonly name: string,
    private _onHand: number,
    private _reserved: number,
  ) {}

  static create(id: string, name: string, initialStock: number): Product {
    if (id.trim() === '') {
      throw new InvalidValueError('Product id must not be empty');
    }
    if (name.trim() === '') {
      throw new InvalidValueError('Product name must not be empty');
    }
    assertNonNegativeInteger(initialStock, 'Initial stock');
    return new Product(id, name, initialStock, 0);
  }

  get onHand(): number {
    return this._onHand;
  }

  get reserved(): number {
    return this._reserved;
  }

  get available(): number {
    return this._onHand - this._reserved;
  }

  canReserve(quantity: number): boolean {
    return quantity <= this.available;
  }

  reserve(quantity: number): void {
    assertPositiveInteger(quantity);
    if (!this.canReserve(quantity)) {
      throw new InsufficientStockError(this.id, quantity, this.available);
    }
    this._reserved += quantity;
  }

  /** Returns previously reserved units to the available pool. */
  release(quantity: number): void {
    this.assertReserved(quantity);
    this._reserved -= quantity;
  }

  /** Reserved units leave the warehouse: they are removed from both reserved and on-hand stock. */
  dispatch(quantity: number): void {
    this.assertReserved(quantity);
    this._reserved -= quantity;
    this._onHand -= quantity;
  }

  private assertReserved(quantity: number): void {
    assertPositiveInteger(quantity);
    if (quantity > this._reserved) {
      throw new InvalidValueError(
        `Cannot use ${quantity} reserved units of product ${this.id}; only ${this._reserved} reserved`,
      );
    }
  }
}

function assertPositiveInteger(quantity: number): void {
  if (!Number.isInteger(quantity) || quantity <= 0) {
    throw new InvalidValueError('Quantity must be a positive integer');
  }
}

function assertNonNegativeInteger(value: number, label: string): void {
  if (!Number.isInteger(value) || value < 0) {
    throw new InvalidValueError(`${label} must be a non-negative integer`);
  }
}

